import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dil_d, int dil_h, int dil_w,
    int groups, int in_channels_per_group, int out_channels_per_group,
    bool has_bias)
{
    extern __shared__ float s_weight[];
    int noc = blockIdx.y;
    int oc = noc % out_channels;
    int n = noc / out_channels;
    int group = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;
    int ic_start = group * in_channels_per_group;
    int kElems = kD * kH * kW;
    int weight_size = in_channels_per_group * kElems;
    for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
        int ic_local = i / kElems;
        int rem = i % kElems;
        int ic = ic_start + ic_local;
        long weight_idx = ((long)ic * out_channels_per_group + oc_in_group) * kElems + rem;
        s_weight[i] = weight[weight_idx];
    }
    __syncthreads();
    long spatial_total = (long)D_out * H_out * W_out;
    long spatial_idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    if (spatial_idx >= spatial_total) return;
    int ow = spatial_idx % W_out;
    long tmp = spatial_idx / W_out;
    int oh = tmp % H_out;
    tmp /= H_out;
    int od = tmp;
    float sum = 0.0f;
    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        int ic = ic_start + ic_local;
        for (int kd = 0; kd < kD; kd++) {
            int t_d = od + pad_d - kd * dil_d;
            if (t_d % stride_d != 0) continue;
            int id = t_d / stride_d;
            if (id < 0 || id >= D_in) continue;
            for (int kh = 0; kh < kH; kh++) {
                int t_h = oh + pad_h - kh * dil_h;
                if (t_h % stride_h != 0) continue;
                int ih = t_h / stride_h;
                if (ih < 0 || ih >= H_in) continue;
                for (int kw = 0; kw < kW; kw++) {
                    int t_w = ow + pad_w - kw * dil_w;
                    if (t_w % stride_w != 0) continue;
                    int iw = t_w / stride_w;
                    if (iw < 0 || iw >= W_in) continue;
                    long input_idx = (((long)n * in_channels + ic) * D_in + id) * H_in * W_in + (long)ih * W_in + iw;
                    int s_idx = (ic_local * kD + kd) * kH * kW + kh * kW + kw;
                    sum += input[input_idx] * s_weight[s_idx];
                }
            }
        }
    }
    if (has_bias) {
        sum += bias[oc];
    }
    long output_idx = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow;
    output[output_idx] = sum;
}
torch::Tensor conv_transpose3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_d, int64_t stride_h, int64_t stride_w,
    int64_t pad_d, int64_t pad_h, int64_t pad_w,
    int64_t out_pad_d, int64_t out_pad_h, int64_t out_pad_w,
    int64_t dil_d, int64_t dil_h, int64_t dil_w,
    int64_t groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int in_channels = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int out_channels_per_group = weight.size(1);
    int out_channels = out_channels_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int in_channels_per_group = in_channels / groups;
    int D_out = (D_in - 1) * stride_d - 2 * pad_d + dil_d * (kD - 1) + out_pad_d + 1;
    int H_out = (H_in - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + out_pad_h + 1;
    int W_out = (W_in - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + out_pad_w + 1;
    auto output = torch::zeros({N, out_channels, D_out, H_out, W_out}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;
    long spatial_total = (long)D_out * H_out * W_out;
    int threads = 256;
    long blocks_x = (spatial_total + threads - 1) / threads;
    long blocks_y = (long)N * out_channels;
    dim3 grid((unsigned int)blocks_x, (unsigned int)blocks_y, 1);
    dim3 block(threads, 1, 1);
    size_t shared_mem_bytes = (size_t)in_channels_per_group * kD * kH * kW * sizeof(float);
    const float* bias_ptr = nullptr;
    torch::Tensor bias_contig;
    if (has_bias) {
        bias_contig = bias.contiguous();
        bias_ptr = bias_contig.data_ptr<float>();
    }
    conv_transpose3d_kernel<<<grid, block, shared_mem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, in_channels, out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        (int)stride_d, (int)stride_h, (int)stride_w,
        (int)pad_d, (int)pad_h, (int)pad_w,
        (int)dil_d, (int)dil_h, (int)dil_w,
        (int)groups, in_channels_per_group, out_channels_per_group,
        has_bias
    );
    return output;
}
"""

